# AUTOGENERATED KERNEL (LLM)
# Source: LLM-generated candidate implementation
# Status: Experimental / uncurated
# Expectation: Correctness-first, performance not representative

import torch
import torch.nn as nn
import triton
import triton.language as tl

batch_size = 4096
dim = 393216


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_SIZE": bs},
        )
        for bs in [32, 64, 128, 256, 512, 1024, 2048, 4096]
    ],
    key=["n_elements"],
)
@triton.jit
def _tanh_kernel(
    x_ptr,
    out_ptr,
    n_elements,
    BLOCK_SIZE: tl.constexpr,
):
    pid = tl.program_id(0)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements

    x = tl.load(x_ptr + offsets, mask=mask, other=0.0)

    # tanh(x) = 2*sigmoid(2x) - 1
    # sigmoid(z) = 1/(1 + exp2(-z * log2(e)))
    inv_ln2: tl.constexpr = 1.4426950408889634
    z = 2.0 * x
    e = tl.math.exp2((-z) * inv_ln2)
    sig = 1.0 / (1.0 + e)
    result = 2.0 * sig - 1.0

    tl.store(out_ptr + offsets, result, mask=mask)


class Model(nn.Module):
    def __init__(self):
        super(Model, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x_flat = x.contiguous().view(-1)
        n_elements = x_flat.numel()
        output_flat = torch.empty_like(x_flat)

        grid = lambda META: (triton.cdiv(n_elements, META["BLOCK_SIZE"]),)
        _tanh_kernel[grid](x_flat, output_flat, n_elements)

        return output_flat.view(x.shape)


def get_inputs():
    x = torch.rand(batch_size, dim, dtype=torch.bfloat16)
    return [x]


def get_init_inputs():
    return []
